using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Configuration;
using Prodimt.Pedidos.Application.Abstractions;

namespace Prodimt.Pedidos.Infrastructure.Authentication;

// Recoverable admin storage is independent of the authentication hash and JWT key.
// The key must survive application releases; it is never generated by this class.
public sealed class AesGcmCustomerAccessTokenProtector(IConfiguration configuration) : ICustomerAccessTokenProtector
{
    public const string ConfigurationKey = "CustomerAccessTokens:EncryptionKey";
    private const string Prefix = "v1.";
    private const string Purpose = "PRODIMT.CustomerAccessToken.v1";
    private const string Unavailable = "La protección de tokens de acceso no está disponible.";
    private const int NonceSize = 12;
    private const int TagSize = 16;
    private const int MaximumPlaintextBytes = 256;
    private const int MaximumEnvelopeCharacters = 1024;
    private static readonly UTF8Encoding Utf8 = new(false, true);

    public string Protect(Guid customerId, Guid tokenId, string plainToken)
    {
        if (customerId == Guid.Empty || tokenId == Guid.Empty || string.IsNullOrWhiteSpace(plainToken)
            || plainToken.Length > MaximumPlaintextBytes)
            throw NotAvailable();
        var key = ReadKey();
        byte[]? plaintext = null;
        try
        {
            plaintext = Utf8.GetBytes(plainToken);
            if (plaintext.Length > MaximumPlaintextBytes) throw NotAvailable();
            var nonce = RandomNumberGenerator.GetBytes(NonceSize);
            var tag = new byte[TagSize];
            var ciphertext = new byte[plaintext.Length];
            using var aes = new AesGcm(key, TagSize);
            aes.Encrypt(nonce, plaintext, ciphertext, tag, AssociatedData(customerId, tokenId));
            var envelope = new byte[NonceSize + TagSize + ciphertext.Length];
            nonce.CopyTo(envelope, 0);
            tag.CopyTo(envelope, NonceSize);
            ciphertext.CopyTo(envelope, NonceSize + TagSize);
            return Prefix + Convert.ToBase64String(envelope);
        }
        catch (Exception ex) when (ex is CryptographicException or ArgumentException or PlatformNotSupportedException)
        { throw NotAvailable(); }
        finally
        {
            CryptographicOperations.ZeroMemory(key);
            if (plaintext is not null) CryptographicOperations.ZeroMemory(plaintext);
        }
    }

    public string Unprotect(Guid customerId, Guid tokenId, string protectedToken)
    {
        if (customerId == Guid.Empty || tokenId == Guid.Empty || protectedToken is null
            || protectedToken.Length > MaximumEnvelopeCharacters || !protectedToken.StartsWith(Prefix, StringComparison.Ordinal))
            throw NotAvailable();
        var key = ReadKey();
        byte[]? plaintext = null;
        try
        {
            var encoded = protectedToken[Prefix.Length..];
            var envelope = Convert.FromBase64String(encoded);
            if (envelope.Length <= NonceSize + TagSize || envelope.Length > NonceSize + TagSize + MaximumPlaintextBytes
                || Convert.ToBase64String(envelope) != encoded)
                throw NotAvailable();
            plaintext = new byte[envelope.Length - NonceSize - TagSize];
            using var aes = new AesGcm(key, TagSize);
            aes.Decrypt(envelope.AsSpan(0, NonceSize), envelope.AsSpan(NonceSize + TagSize),
                envelope.AsSpan(NonceSize, TagSize), plaintext, AssociatedData(customerId, tokenId));
            var result = Utf8.GetString(plaintext);
            if (string.IsNullOrWhiteSpace(result)) throw NotAvailable();
            return result;
        }
        catch (Exception ex) when (ex is CryptographicException or ArgumentException or FormatException or PlatformNotSupportedException)
        { throw NotAvailable(); }
        finally
        {
            CryptographicOperations.ZeroMemory(key);
            if (plaintext is not null) CryptographicOperations.ZeroMemory(plaintext);
        }
    }

    private byte[] ReadKey()
    {
        var encoded = configuration[ConfigurationKey];
        if (string.IsNullOrEmpty(encoded) || encoded.Length != 44) throw NotAvailable();
        byte[] key;
        try { key = Convert.FromBase64String(encoded); }
        catch (FormatException) { throw NotAvailable(); }
        if (key.Length == 32 && Convert.ToBase64String(key) == encoded) return key;
        CryptographicOperations.ZeroMemory(key);
        throw NotAvailable();
    }

    private static byte[] AssociatedData(Guid customerId, Guid tokenId)
        => Utf8.GetBytes($"{Purpose}|{customerId:N}|{tokenId:N}");

    private static InvalidOperationException NotAvailable() => new(Unavailable);
}
